import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    K = int(input_data[1])

    count = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            if (a + b) % K != 0:
                continue
            for c in range(1, N + 1):
                if (b + c) % K == 0 and (c + a) % K == 0:
                    count += 1
    print(count)

if __name__ == "__main__":
    solve()
